import type { DemoClassifieds } from "./worker";

export interface ActivityArea {
  categoryId: string;
  subcategoryId: string;
}

/**
 * Resolves the data files' category/subcategory slug pairs to the ids the
 * catalogue seed created. Ids are generated by the Worker, so a data file can
 * only ever name a subcategory by its slugs. Each pair is read once per run.
 */
export function createActivityAreaResolver(classifieds: DemoClassifieds) {
  const cache = new Map<string, Promise<ActivityArea | null>>();

  return async function resolve(categorySlug: string, subcategorySlug: string, owner: string): Promise<ActivityArea> {
    const key = `${categorySlug}/${subcategorySlug}`;
    let resolved = cache.get(key);
    if (!resolved) {
      resolved = classifieds.read<ActivityArea | null>("subcategories.resolve", { categorySlug, subcategorySlug });
      cache.set(key, resolved);
    }
    const area = await resolved;
    if (!area) throw new Error(`Demo ${owner} names "${key}", which the category catalogue does not define.`);
    return { categoryId: area.categoryId, subcategoryId: area.subcategoryId };
  };
}

export type ActivityAreaResolver = ReturnType<typeof createActivityAreaResolver>;
